+int sqlite3Fts5PoslistNext64(
+  const u8 *a, int n,             /* Buffer containing poslist */
+  int *pi,                        /* IN/OUT: Offset within a[] */
+  i64 *piOff                      /* IN/OUT: Current offset */
+){
+  int i = *pi;
+  if( i>=n ){
+    /* EOF */
+    return 1;  
+  }else{
+    i64 iOff = *piOff;
+    int iVal;
+    i += getVarint32(&a[i], iVal);
+    if( iVal==1 ){
+      i += getVarint32(&a[i], iVal);
+      iOff = ((i64)iVal) << 32;
+      i += getVarint32(&a[i], iVal);
+    }
+    *piOff = iOff + (iVal-2);
+    *pi = i;
+    return 0;
+  }
+}
